@push('scripts')<script>document.addEventListener('click',e=>{const b=e.target.closest('[data-reject]');if(b){const f=document.getElementById(b.dataset.reject);f?.classList.toggle('open');f?.querySelector('textarea')?.focus();}const s=e.target.closest('.rr-history>summary,.rr-card>summary');if(!s)return;const d=s.parentElement;if(d.classList.contains('rr-card'))document.querySelectorAll('.rr-card[open]').forEach(x=>{if(x!==d)x.open=false});});</script>@endpush
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const history=document.querySelector('.rr-history'),active=document.querySelector('.rr-section:not(.rr-history)');if(!history||!active)return;const head=active.querySelector(':scope>.rr-head');if(!head)return;head.tabIndex=0;head.setAttribute('role','button');head.setAttribute('aria-expanded','true');const toggle=()=>{const open=!active.classList.toggle('rr-collapsed');head.setAttribute('aria-expanded',String(open));history.open=false};head.addEventListener('click',toggle);head.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}});history.querySelector(':scope>summary')?.addEventListener('click',()=>active.classList.add('rr-collapsed'));});</script><style>.rr-active{} .rr-section:not(.rr-history).rr-collapsed>:not(.rr-head){display:none}.rr-section:not(.rr-history).rr-collapsed .rr-head{border-bottom:0}</style>@endpush
